referenceSolutions.javascript:
function drawerGridsFirstQualifyingSlip(drawers, k) {
  const a=drawers; let out=[];
  for(const row of a){let s=0;for(const x of row)s+=x;out.push(s);}
  return out.find(x=>x>=k)??-1;
}

